// Помилка поля, яку вже час показати: після спроби відправити форму або
// коли в полі щось введено. Порожнє поле щойно відкритої модалки не
// «червоніє» лише тому, що фокус перейшов на вікно.
export const visibleError = (form, name) => {
    const error = form.errors[name];
    if (typeof error !== 'string')
        return undefined;
    const value = form.values[name];
    const typed = typeof value === 'string' && value !== '';
    return form.submitCount > 0 || typed ? error : undefined;
};
